pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == 0);
        vm.assume(v.length == 0);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", _tos, v));
        // The reference reverts (ok == false) because _tos.length > 0 is required.
        // The mutant does not revert (ok == true) because _tos.length >= 0 is always true.
        assertTrue(!ok, "Should revert when _tos is empty");
    }
}

