pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Restrict to empty _tos array
        vm.assume(_tos.length == 0);
        // Ensure v array length matches (optional, but avoids array length mismatch revert)
        vm.assume(v.length == 0);
        // Set msg.sender to the from address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // The call should revert for the reference; capture the revert boolean
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
        assertTrue(!success, "transfer with empty _tos must revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == 0);
        // Only drive one call: transfer with empty _tos
        bool reverted = false;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}
